    demoBanksTitle: { es: "Bancos de demostración disponibles", en: "Available demo banks", fr: "Banques de démonstration disponibles", it: "Banche demo disponibili", pt: "Bancos de demonstração disponíveis" },
    connectBtn: { es: "Conectar", en: "Connect", fr: "Connecter", it: "Collega", pt: "Conectar" },
    csvImportTitle: { es: "📄 Importar movimientos reales desde CSV", en: "📄 Import real transactions from CSV", fr: "📄 Importer des mouvements réels depuis un CSV", it: "📄 Importa movimenti reali da CSV", pt: "📄 Importar movimentos reais de CSV" },
    csvImportHint: { es: "Descarga el extracto de tu banca online en formato CSV y impórtalo aquí. El archivo se procesa en tu dispositivo: nunca se envía a ningún servidor.", en: "Download your online banking statement as CSV and import it here. The file is processed on your device: it's never sent to any server.", fr: "Téléchargez le relevé de votre banque en ligne au format CSV et importez-le ici. Le fichier est traité sur votre appareil : il n'est jamais envoyé à un serveur.", it: "Scarica l'estratto conto della tua banca online in formato CSV e importalo qui. Il file viene elaborato sul tuo dispositivo: non viene mai inviato a nessun server.", pt: "Baixe o extrato do seu banco online em formato CSV e importe-o aqui. O arquivo é processado no seu dispositivo: nunca é enviado a nenhum servidor." },
